"\"\"\"Re-exports ModalityDropout from preprocessing.missingness.\n\nThis module is kept for backward compatibility and clear module organization.\nThe actual implementation lives in src.preprocessing.missingness.\n\"\"\"\nfrom src.preprocessing.missingness import ModalityDropout  # noqa: F401\nimport numpy as np\nimport torch\nfrom typing import Optional\n\n\ndef apply_modality_mask(\n    embedding: torch.Tensor,\n    mask_value: torch.Tensor,\n) -> torch.Tensor:\n    \"\"\"Apply a scalar mask to an embedding tensor.\n\n    Args:\n        embedding: (batch, dim) embedding.\n        mask_value: (batch,) float mask, 1.0 = keep, 0.0 = zero out.\n\n    Returns:\n        Masked embedding.\n    \"\"\"\n    return embedding * mask_value.unsqueeze(1)\n"